CREATE TABLE `product` (
  `ProductID` int NOT NULL AUTO_INCREMENT,
  `ProductName` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `CategoryID` int NOT NULL,
  `ProductPrice` int NOT NULL,
  `quantity` int NOT NULL DEFAULT '0',
  `status` enum('Active','Inactive') DEFAULT 'Active',
  `description` text,
  `ingredients` text,
  `rating` float DEFAULT '5',
  `image` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`ProductID`),
  KEY `CategoryID` (`CategoryID`),
  CONSTRAINT `Product_ibfk_1` FOREIGN KEY (`CategoryID`) REFERENCES `category` (`category_id`),
  CONSTRAINT `Product_chk_1` CHECK ((`ProductPrice` >= 0)),
  CONSTRAINT `Product_chk_2` CHECK ((`quantity` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
