INSERT INTO `product` VALUES (1,'Bánh mì thịt',1,20000,65,'Active','Bánh mì nóng giòn kẹp thịt heo nướng than hoa thơm lừng, rưới nước sốt đậm đà đặc trưng của tiệm.','Bánh mì, thịt heo nướng, pate gan, dưa leo, ngò rí, tương ớt',4.5,'banhmithit.png'),(2,'Bánh mì chay',1,15000,61,'Active','Lựa chọn thanh đạm nhưng vẫn đầy đủ dinh dưỡng, vị đậm đà không kém bánh mì mặn.','Bánh mì, chả lụa chay, bì chay, đậu khuôn, nước tương, rau sống',5,'banhmichay.png'),(3,'Bánh mì trứng',1,18000,75,'Active','Bánh mì nóng giòn kẹp trứng ốp la lòng đào béo ngậy, rưới nước sốt đậm đà đặc trưng của tiệm.','Bánh mì, trứng ốp la, pate gan, dưa leo, ngò rí, tương ớt',0,'banhmitrung.png'),(4,'Hamburger bò phô mát',2,25000,78,'Active','Burger chuẩn vị Mỹ với lớp thịt bò mọng nước và phô mai tan chảy béo ngậy.','Vỏ bánh burger mềm, thịt bò băm nướng, phô mai Cheddar, cà chua, xà lách',0,'hamburger_bo.png'),(5,'Pizza Hải Sản đút lò (Size M)',2,85000,80,'Active','Pizza đế mỏng giòn tan, phủ đầy hải sản tươi ngon và phô mai kéo sợi cực hấp dẫn.','Bột mì, tôm, mực, sốt cà chua, ớt chuông, phô mai Mozzarella',5,'pizzaphomai.png'),(6,'Croissant Bơ tỏi',3,25000,79,'Active','Bánh sừng trâu nướng ngập ngụa bơ tỏi thơm nức mũi, lớp vỏ ngoài giòn rụm.','Bột mì ngàn lớp, bơ lạt, tỏi băm, ngò tây, phô mai kéo sợi',4,'croissant_botoi.png'),(7,'Bánh Tiramisu Ý',3,35000,65,'Active','Bánh ngọt tráng miệng trứ danh của Ý, mang hương vị cà phê và cacao vô cùng quyến rũ.','Phô mai Mascarpone, bột cacao nguyên chất, cà phê espresso, bánh sâm panh',4,'tiramisu.png'),(8,'Mousse Chanh Dây',3,30000,80,'Active','Bánh Mousse chua ngọt thanh mát, tan ngay trong miệng. Giải ngấy cực kỳ hiệu quả.','Kem tươi whipping, cốt chanh dây, đường, gelatin, đế bánh quy bơ',5,'mousse_chanhday.png'),(9,'Trà đào cam sả',4,25000,0,'Active','Thức uống giải khát quốc dân, sự kết hợp hoàn hảo giữa vị chua, ngọt và hương sả thơm lừng.','Trà đen, đào ngâm sệt, cam vàng tươi, sả cây, đá viên',0,'trachanh.png'),(10,'Cà phê sữa đá truyền thống',4,20000,78,'Active','Cà phê pha phin đậm đặc, bừng tỉnh sự tập trung cho một ngày làm việc.','Cà phê Robusta nguyên chất, sữa đặc có đường, đá',5,'caphesuada.png'),(11,'Trà sữa Trân châu đường đen',4,25000,80,'Active','Sữa tươi thanh trùng béo ngậy kết hợp cùng trân châu nấu đường đen dẻo dai sần sật.','Sữa tươi không đường, hồng trà, trân châu đen, siro đường đen Hàn Quốc',4.5,'trasuatranchau.png'),(12,'Matcha đá xay phủ kem',4,28000,80,'Active','Trà xanh đá xay mát lạnh, đắng nhẹ hậu ngọt, phủ lên trên là lớp kem béo ngậy.','Bột trà xanh Matcha Nhật Bản, sữa tươi, kem tươi whipping, đá',0,'matchadaxay.png');
/*!40000 ALTER TABLE `product` ENABLE KEYS */;
UNLOCK TABLES;

